from math import copysign, isfinite, isclose, nan, inf, isinf

def test_sign_fn(sign, x):
    sign_of_x = sign(x)

    # test sign
    assert copysign(1.0, x.real) == copysign(1.0, sign_of_x.real)
    assert copysign(1.0, x.imag) == copysign(1.0, sign_of_x.imag)

    # test magnitude
    if x == 0:
        assert sign_of_x == 0
    elif x.imag == 0 or (isfinite(x.imag) and isinf(x.real)):  # a real number
        assert sign_of_x.imag == 0
        assert (x.real == x.real) == (sign_of_x.real == sign_of_x.real) == (abs(sign_of_x.real) == 1)
    elif x.real == 0 or (isfinite(x.real) and isinf(x.imag)):  # an imaginary number
        assert sign_of_x.real == 0
        assert (x.imag == x.imag) == (sign_of_x.imag == sign_of_x.imag) == (abs(sign_of_x.imag) == 1)
    elif isfinite(x.real) and isfinite(x.imag):
        assert isclose(abs(sign_of_x), 1)
        assert isclose(x.real*sign_of_x.imag, x.imag*sign_of_x.real)
    else:
