def compliant_sign_impl(x):
    if isinstance(x, Real):
        if x > 0: return type(x)(1)
        if x < 0: return type(x)(-1)
        return x
    if isinstance(x, Complex):
        if x == 0: return x
        real, imag = x.real / abs(x), x.imag / abs(x)
        if real != real or imag != imag:
            real, imag = (
                real and x.real and copysign(imag or 1, x.real),
                imag and x.imag and copysign(real or 1, x.imag)
            )
        return type(x)(real, imag)
    raise TypeError


