Here is the C code I am using. I've written it as a test case against my own private BLAS library. I have a private library so that I can iterate/test/evaluate code changes more efficiently.

So far, I am unable to reproduce this in my own BLAS library (which uses the same Windows threading code). That is not to say that there is not an issue with this code in OpenBLAS, only that it isn't an obvious and immediate failure elsewhere.

```C
#include <stdio.h>
#include <string.h>
#include <time.h>
#include "test.h"
#include "cblas.h"

#define size 500000
#define checks 500
#define epsilon (1e-5 + 1e-8)

typedef float dtype;

dtype x[size];
dtype src[size][2];
dtype matrix[] = {0.0, 1.0, 1.0, 0.0};
dtype expected[size][2];
int mismatches[checks];
dtype result[size][2];

//------------------------------------------------------
//
//------------------------------------------------------
static int isclose()
{
	int count = 0;

	for (int i = 0; i < size; i++)
	{
		dtype delta = fabs(result[i][0] - expected[i][0]);
		if (delta > epsilon)
			count++;

		delta = fabs(result[i][1] - expected[i][1]);
		if (delta > epsilon)
			count++;
	}

	return count;
}

//
void clear_result()
{
	for (int i = 0; i < size; i++)
	{
		result[i][0] = 0.0;
		result[i][1] = 0.0;
	}
}

//------------------------------------------------------
//
//------------------------------------------------------
static void test_win_threads()
{
	for (int i = 0; i < size; i++)
	{
		x[i] = (dtype)i;
		src[i][0] = x[i];
		src[i][1] = -10.0 * x[i];
		expected[i][0] = -10.0 * x[i];
		expected[i][1] = x[i];
	}

	for (int i = 0; i < checks; i++)
	{
		clear_result();

		cblas_sgemm(CblasNoTrans, CblasNoTrans, size, 2, 2, 1.0, src, 2, matrix, 2, 1.0, result, 2);
		mismatches[i] = isclose();
		if (mismatches[i] > 0)
			printf("%d mismatching elements in multiplication %d", mismatches[i], i);
	}

	puts("done");
}

//------------------------------------------------------
//
//------------------------------------------------------
int main(int argc, char *argv[])
{
	test_win_threads();

	return 0;
}
